{"path":"fees.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Investment & Options — {{BUSINESS_NAME}}</title>
  <style>
    :root{--glass:#ffffff22;--glass-2:#ffffff18;--accent:#7b4bff;--accent-2:#00c2a8;--muted:#cbd5e1;--bg:#0f1722}
    html,body{height:100%;margin:0;font-family:Inter, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial;color:#e6eef6;background:radial-gradient(1200px 600px at 10% 10%, #112233 0%, #071018 30%, #061018 100%), #061018;}
    /* background pattern (external file expected at assets/img/pattern.svg) */
    body::before{content:"";position:fixed;inset:0;background-image:url('assets/img/pattern.svg');opacity:0.12;mix-blend-mode:overlay;z-index:0}
    .wrap{position:relative;z-index:1;max-width:1100px;margin:40px auto;padding:36px;border-radius:14px;background:linear-gradient(180deg, rgba(255,255,255,0.03), rgba(255,255,255,0.02));box-shadow:0 6px 32px rgba(2,6,23,0.6);backdrop-filter:blur(10px);border:1px solid rgba(255,255,255,0.04)}
    header{display:flex;align-items:center;justify-content:space-between;gap:20px}
    .brand{display:flex;align-items:center;gap:12px}
    .logo{width:46px;height:46px;border-radius:10px;background:linear-gradient(135deg,var(--accent),var(--accent-2));display:flex;align-items:center;justify-content:center;color:white;font-weight:700}
    nav a{color:var(--muted);text-decoration:none;margin-left:18px;font-size:0.95rem}
    h1{margin:18px 0 4px;font-size:1.6rem}
    p.lead{color:#cfe7f8;margin:0 0 18px}

    .grid{display:grid;grid-template-columns:1fr 360px;gap:22px}
    .card{background:linear-gradient(180deg, rgba(255,255,255,0.02), rgba(255,255,255,0.01));border-radius:12px;padding:18px;border:1px solid rgba(255,255,255,0.03)}

    /* pricing comparator */
    .toggle{display:inline-flex;background:rgba(255,255,255,0.03);padding:6px;border-radius:999px;border:1px solid rgba(255,255,255,0.04)}
    .toggle button{background:transparent;border:0;padding:8px 14px;border-radius:999px;color:var(--muted);cursor:pointer}
    .toggle button.active{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:white;box-shadow:0 6px 18px rgba(123,75,255,0.12)}

    .pricing-row{display:flex;align-items:center;justify-content:space-between;padding:14px;border-radius:10px;margin-bottom:12px}
    .pricing-row .meta{display:flex;flex-direction:column}
    .price{font-weight:700;font-size:1.2rem;color:#eaf6ff}
    .price .num{font-size:1.45rem;color:var(--accent-2);display:inline-block;min-width:72px;text-align:right}
    .hint{font-size:0.86rem;color:var(--muted)}

    .mood{display:flex;gap:8px;margin-top:12px;flex-wrap:wrap}
    .mood button{padding:8px 12px;border-radius:999px;border:1px dashed rgba(255,255,255,0.04);background:transparent;color:var(--muted);cursor:pointer}
    .mood button.active{background:rgba(0,194,168,0.08);border-style:solid;color:var(--accent-2);}

    .recommend{margin-top:12px;padding:12px;border-radius:10px;background:linear-gradient(180deg, rgba(255,255,255,0.01), rgba(255,255,255,0.00));border:1px solid rgba(255,255,255,0.02)}
    .cta{display:inline-block;margin-top:12px;padding:10px 16px;border-radius:10px;background:linear-gradient(90deg,var(--accent),var(--accent-2));color:white;text-decoration:none}

    .fine{font-size:0.82rem;color:#9fb0c6;margin-top:12px}
    footer{margin-top:18px;font-size:0.82rem;color:#9fb0c6}

    @media(max-width:900px){.grid{grid-template-columns:1fr;}.wrap{margin:18px}}
  </style>
</head>
<body>
  <div class="wrap">
    <header>
      <div class="brand">
        <div class="logo">TP</div>
        <div>
          <div style="font-weight:700">{{BUSINESS_NAME}}</div>
          <div style="font-size:0.86rem;color:var(--muted)">{{CITY}}, {{STATE}}</div>
        </div>
      </div>
      <nav aria-label="Primary">
        <a href="index.html">Welcome</a>
        <a href="about.html">Who I Am</a>
        <a href="specialties.html">Focus Areas</a>
        <a href="approach.html">How I Work</a>
        <a href="fees.html">Investment</a>
        <a href="faq.html">Questions</a>
        <a href="book.html">Book</a>
        <a href="contact.html">Connect</a>
      </nav>
    </header>

    <main>
      <h1>Investment & Options</h1>
      <p class="lead">Flexible choices to match where you are. Transparent pricing, compassionate boundaries, and a pathway that meets your energy and time.</p>

      <div class="grid">
        <section class="card">
          <div style="display:flex;justify-content:space-between;align-items:center">
            <div>
              <strong>Compare pricing</strong>
              <div class="hint">See values as single sessions, packaged support, or cohort subscription</div>
            </div>
            <div class="toggle" role="tablist" aria-label="Pricing view">
              <button id="view-session" class="active" aria-pressed="true">Per session</button>
              <button id="view-package" aria-pressed="false">Package / Cohort</button>
            </div>
          </div>

          <div id="pricing-list" style="margin-top:14px">
            <div class="pricing-row">
              <div class="meta"><div style="font-weight:700">One-on-one clinical session</div><div class="hint">50 minutes, therapeutic focus</div></div>
              <div class="price"><span class="num" data-session="150" data-package="840" id="price-session">$150</span></div>
            </div>

            <div class="pricing-row">
              <div class="meta"><div style="font-weight:700">Six-session package</div><div class="hint">Structured short-term work</div></div>
              <div class="price"><span class="num" data-session="840" data-package="840" id="price-package">$840</span></div>
            </div>

            <div class="pricing-row">
              <div class="meta"><div style="font-weight:700">Cohort support (monthly)</div><div class="hint">Group learning + weekly check-ins</div></div>
              <div class="price"><span class="num" data-session="65" data-package="65" id="price-cohort">$65</span></div>
            </div>

            <div style="margin-top:8px;font-size:0.9rem;color:var(--muted)">All services billed privately. I provide receipts you may submit to your insurance — I do not bill insurance directly.</div>
          </div>

          <div class="fine">Package pricing assumes sessions scheduled within 6 months; single-session pricing applies otherwise. If cost is a barrier, we can explore sliding-scale openings or alternative cohort access.</div>
        </section>

        <aside class="card">
          <strong>Tell me how you're feeling</strong>
          <div class="mood" role="list" aria-label="Mood chooser">
            <button data-key="stuck" class="active">Stuck</button>
            <button data-key="overwhelmed">Overwhelmed</button>
            <button data-key="curious">Curious</button>
            <button data-key="grieving">Grieving</button>
          </div>

          <div class="recommend" id="recommend">
            <div style="font-weight:700" id="rec-title">Short-term focused sessions</div>
            <div id="rec-copy" style="color:var(--muted);margin-top:6px">When you're feeling stuck, targeted one-on-one work helps clarify next steps. A six-session package can offer structure without long-term commitment.</div>
            <a id="rec-cta" class="cta" href="{{PRIMARY_CTA_URL}}">Book a focused session</a>
          </div>

          <div style="font-size:0.85rem;color:var(--muted);margin-top:10px">
            Confidentiality: sessions are held under clinical confidentiality except in legally-described exceptions (harm to self/others, abuse). My practice focuses on therapy and coaching for life transitions; I do not provide emergency/crisis services.
          </div>
        </aside>
      </div>

      <div style="margin-top:18px" class="card">
        <strong>Notes on format</strong>
        <p class="fine">Cohort participants meet weekly for facilitated learning, and receive access to a private cohort check-in. Cohorts are time-limited learning groups, not ongoing individual therapy. If you are considering intensive clinical work, we can discuss appropriate referrals or a private therapy plan.</p>
      </div>

      <footer>
        <div>Need to talk before booking? Call <a href="tel:{{PHONE}}">{{PHONE}}</a> or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>.</div>
        <div style="margin-top:6px;color:var(--muted)">Cancellations: please give 48-hour notice to avoid charge. For urgent concerns, contact local crisis resources — if you are in immediate danger, call emergency services.</div>
      </footer>
    </main>
  </div>

  <script>
    // Pricing comparator - animated numeric transition
    function animateNumber(el, start, end, duration){
      let startTime = null;
      function step(time){
        if(!startTime) startTime = time;
        const progress = Math.min((time - startTime) / duration, 1);
        const value = Math.round(start + (end - start) * progress);
        el.textContent = '$' + value;
        if(progress < 1) requestAnimationFrame(step);
      }
      requestAnimationFrame(step);
    }

    const btnSession = document.getElementById('view-session');
    const btnPackage = document.getElementById('view-package');
    const priceEls = [document.getElementById('price-session'), document.getElementById('price-package'), document.getElementById('price-cohort')];

    function setMode(mode){
      // mode: 'session' or 'package'
      [btnSession, btnPackage].forEach(b=>b.classList.remove('active'));
      if(mode === 'session'){btnSession.classList.add('active');btnSession.setAttribute('aria-pressed','true');btnPackage.setAttribute('aria-pressed','false')}
      else{btnPackage.classList.add('active');btnPackage.setAttribute('aria-pressed','true');btnSession.setAttribute('aria-pressed','false')}

      priceEls.forEach(el=>{
        const start = parseInt(el.textContent.replace(/[^0-9]/g,''))||0;
        const target = parseInt(el.dataset[mode])||start;
        animateNumber(el,start,target,500);
      });
    }

    btnSession.addEventListener('click',()=>setMode('session'));
    btnPackage.addEventListener('click',()=>setMode('package'));

    // Mood-to-Method selector
    const moodBtns = document.querySelectorAll('.mood button');
    const recTitle = document.getElementById('rec-title');
    const recCopy = document.getElementById('rec-copy');
    const recCta = document.getElementById('rec-cta');

    const moodMap = {
      stuck: {title:'Short-term focused sessions',copy:'When you feel stuck, we often benefit from a few targeted sessions to name patterns and try new experiments. A six-session plan provides structure and gentle accountability.',cta:'Book a focused session',href:'{{PRIMARY_CTA_URL}}?type=package'},
      overwhelmed: {title:'Gentle cadence — cohort support',copy:'If overwhelm is the core, the cohort structure offers weekly rhythm, shared learning, and lighter individual check-ins. It’s collaborative and paced.',cta:'Reserve cohort spot',href:'{{PRIMARY_CTA_URL}}?type=cohort'},
      curious: {title:'Exploratory intake session',copy:'Curiosity is welcome. A single intake session helps us map priorities and design a plan — whether ongoing sessions or cohort learning.',cta:'Schedule an intake',href:'{{PRIMARY_CTA_URL}}?type=intake'},
      grieving: {title:'Supportive sessions & paced care',copy:'Grief benefits from space that is both steady and sensitive. Short-term sessions can hold immediate needs while we consider a longer arc if that feels right.',cta:'Book supportive work',href:'{{PRIMARY_CTA_URL}}?type=grief'}
    };

    function selectMood(key, btn){
      moodBtns.forEach(b=>b.classList.remove('active'));
      btn.classList.add('active');
      const cfg = moodMap[key] || moodMap.stuck;
      recTitle.textContent = cfg.title;
      recCopy.textContent = cfg.copy;
      recCta.textContent = cfg.cta;
      recCta.setAttribute('href',cfg.href);
    }

    moodBtns.forEach(b=>b.addEventListener('click',(e)=>{
      selectMood(e.currentTarget.dataset.key, e.currentTarget);
    }));

    // initial state
    setMode('session');
    selectMood('stuck', document.querySelector('.mood button[data-key="stuck"]'));
  </script>
</body>
</html>"} 
{"path":"faq.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Frequently Asked — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#071018;--card:#ffffff08;--accent:#7b4bff;--muted:#9fb0c6}
    html,body{height:100%;margin:0;font-family:Inter, system-ui, -apple-system, "Segoe UI", Roboto, Arial;color:#e6eef6;background:linear-gradient(180deg,#071018 0%,#04101a 100%)}
    body::after{content:'';position:fixed;inset:0;background-image:url('assets/img/pattern.svg');opacity:0.08;mix-blend-mode:overlay}
    .outer{max-width:920px;margin:36px auto;padding:26px;border-radius:12px;background:linear-gradient(180deg,rgba(255,255,255,0.02),rgba(255,255,255,0.01));border:1px solid rgba(255,255,255,0.03);backdrop-filter:blur(6px)}
    header{display:flex;justify-content:space-between;align-items:center}
    nav a{color:var(--muted);text-decoration:none;margin-left:14px}
    h1{margin:10px 0}
    .qa{margin-top:18px}
    .q{padding:14px;background:var(--card);border-radius:10px;border:1px solid rgba(255,255,255,0.02);margin-bottom:10px}
    .q h3{margin:0 0 8px;font-size:1rem}
    .q p{margin:0;color:var(--muted);font-size:0.95rem}
    .small{font-size:0.82rem;color:var(--muted);margin-top:12px}
    .muted{color:var(--muted)}
    .cta{display:inline-block;padding:10px 14px;border-radius:10px;background:linear-gradient(90deg,var(--accent),#00c2a8);color:white;text-decoration:none;margin-top:12px}
  </style>
</head>
<body>
  <div class="outer">
    <header>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:0.86rem;color:var(--muted)">{{CITY}}, {{STATE}}</div>
      </div>
      <nav>
        <a href="index.html">Welcome</a>
        <a href="about.html">Who I Am</a>
        <a href="specialties.html">Focus Areas</a>
        <a href="approach.html">How I Work</a>
        <a href="fees.html">Investment</a>
        <a href="book.html">Book</a>
      </nav>
    </header>

    <main>
      <h1>Questions people often ask</h1>
      <p class="small">Below are practical answers from a clinician’s perspective. If you don’t see your question, email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> and I’ll reply within a few business days.</p>

      <section class="qa">
        <div class="q">
          <h3>How do cohorts differ from individual therapy?</h3>
          <p>Think of cohorts as learning cohorts: shared curriculum, group discussion, and periodic individual check-ins. They are excellent for building skills and steady practices. Individual therapy offers private clinical attention tailored to your personal history and safety needs.</p>
        </div>

        <div class="q">
          <h3>Can I use insurance?</h3>
          <p>I do not bill insurance directly. I can provide a superbill (receipt) you may submit to your carrier. Coverage depends on your plan. If insurance is required, I can suggest clinicians who accept it.</p>
        </div>

        <div class="q">
          <h3>What if I’m in crisis?</h3>
          <p>I do not provide crisis services. If you are in immediate danger, call emergency services. For urgent mental health crises, contact local crisis lines or 988 if you are in the U.S. If you are unsure, call your local emergency number.</p>
        </div>

        <div class="q">
          <h3>How is confidentiality handled?</h3>
          <p>Sessions are protected under clinical confidentiality. Exceptions include imminent risk of harm to self or others, suspected abuse of a vulnerable person, or other legally required reporting. We’ll review limits of confidentiality during our intake.</p>
        </div>

        <div class="q">
          <h3>What if I can’t afford standard rates?</h3>
          <p>I try to keep a limited number of sliding-scale openings and offer cohort scholarships when possible. Cost should not be a barrier—reach out and we can discuss options candidly.</p>
        </div>

        <div class="q">
          <h3>Do you work with medication management?</h3>
          <p>I do not prescribe medications. If medication evaluation is something you need, I can coordinate with or refer to prescribers as part of a collaborative plan.</p>
        </div>

        <div class="q">
          <h3>How long before I notice change?</h3>
          <p>Every person’s timeline is different. Some people feel clearer after a few sessions; others benefit from longer engagement. My approach prioritizes practical steps we can test together. There are no guarantees, only a shared process.</p>
        </div>
      </section>

      <div style="margin-top:18px">
        <strong>Still unsure?</strong>
        <p class="small">You can choose a single intake session to explore fit and plan a path forward — that can include cohort participation or a sequence of private sessions.</p>
        <a class="cta" href="book.html">Schedule an intake</a>
      </div>

      <div style="margin-top:18px" class="small">
        Confidentiality and scope: This practice provides psychotherapy and coaching for life transitions. If needs exceed the scope of what I offer, I will discuss referrals. For urgent safety concerns, contact local emergency services or crisis lines immediately.
      </div>
    </main>
  </div>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Book — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#071018;--glass:#ffffff10;--accent:#7b4bff;--accent-2:#00c2a8;--muted:#a8c0d8}
    html,body{height:100%;margin:0;font-family:Inter, system-ui, -apple-system, "Segoe UI", Roboto, Arial;color:#e9f6ff;background:linear-gradient(180deg,#061018 0%,#071624 100%)}
    body::before{content:'';position:fixed;inset:0;background-image:url('assets/img/pattern.svg');opacity:0.09;mix-blend-mode:overlay}
    .panel{max-width:920px;margin:34px auto;padding:26px;border-radius:14px;background:linear-gradient(180deg,rgba(255,255,255,0.02),rgba(255,255,255,0.01));border:1px solid rgba(255,255,255,0.03);backdrop-filter:blur(8px)}
    header{display:flex;justify-content:space-between;align-items:center}
    nav a{color:var(--muted);text-decoration:none;margin-left:14px}
    h1{margin:10px 0}
    .split{display:grid;grid-template-columns:1fr 360px;gap:18px;margin-top:18px}
    .card{background:rgba(255,255,255,0.02);padding:16px;border-radius:10px;border:1px solid rgba(255,255,255,0.02)}
    label{display:block;font-size:0.9rem;margin-bottom:6px}
    input,select,textarea{width:100%;padding:10px;border-radius:8px;border:1px solid rgba(255,255,255,0.04);background:transparent;color:inherit}
    .moods{display:flex;gap:8px;flex-wrap:wrap}
    .moods button{padding:8px 10px;border-radius:999px;border:1px solid rgba(255,255,255,0.04);background:transparent;color:var(--muted);cursor:pointer}
    .moods button.active{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:white}
    .rec{margin-top:12px}
    .cta{display:inline-block;padding:12px 16px;border-radius:12px;background:linear-gradient(90deg,var(--accent),var(--accent-2));color:white;text-decoration:none}
    .fine{font-size:0.83rem;color:var(--muted);margin-top:10px}
    .svgbox{display:flex;align-items:center;justify-content:center;height:100%;}
    @media(max-width:900px){.split{grid-template-columns:1fr}} 
  </style>
</head>
<body>
  <div class="panel">
    <header>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:0.86rem;color:var(--muted)">{{CITY}}, {{STATE}}</div>
      </div>
      <nav>
        <a href="index.html">Welcome</a>
        <a href="about.html">Who I Am</a>
        <a href="specialties.html">Focus Areas</a>
        <a href="approach.html">How I Work</a>
        <a href="fees.html">Investment</a>
        <a href="faq.html">Questions</a>
      </nav>
    </header>

    <main>
      <h1>Schedule a session or join a cohort</h1>
      <p class="fine">Pick what fits your rhythm. Your selection helps me suggest the right format — intake, short-term series, or cohort learning.</p>

      <div class="split">
        <section class="card">
          <form id="book-form" action="{{PRIMARY_CTA_URL}}" method="get">
            <label for="name">Your name</label>
            <input id="name" name="name" required placeholder="First & last">

            <label for="email">Email</label>
            <input id="email" name="email" type="email" required placeholder="you@email.com">

            <label for="phone">Phone (optional)</label>
            <input id="phone" name="phone" placeholder="(555) 555-5555">

            <label>How are you feeling right now?</label>
            <div class="moods" role="list" id="mood-list">
              <button type="button" data-key="stuck" class="active">Stuck</button>
              <button type="button" data-key="overwhelmed">Overwhelmed</button>
              <button type="button" data-key="curious">Curious</button>
              <button type="button" data-key="grieving">Grieving</button>
            </div>

            <input type="hidden" name="mood" id="mood-field" value="stuck">
            <input type="hidden" name="recommended" id="rec-field" value="package">

            <div class="rec card" id="recommendation">
              <div style="font-weight:700" id="rec-head">Short-term focused work</div>
              <div id="rec-body" class="fine" style="margin-top:6px;color:var(--muted)">A short package of sessions can help you test small changes and gain momentum. If you prefer a paced group, I’ll point you to the next cohort.</div>
            </div>

            <div style="margin-top:14px">
              <button class="cta" id="submit-btn">Book a focused session</button>
            </div>

            <div class="fine">Privacy: Your information is confidential except where required by law. This booking is not a substitute for emergency care. For crisis support, call local emergency services now.</div>
          </form>
        </section>

        <aside class="card svgbox">
          <div style="max-width:260px">
            <svg viewBox="0 0 240 220" width="100%" aria-hidden="true">
              <defs>
                <linearGradient id="g1" x1="0" x2="1"><stop offset="0" stop-color="#7b4bff"/><stop offset="1" stop-color="#00c2a8"/></linearGradient>
              </defs>
              <rect x="6" y="6" width="228" height="208" rx="18" fill="rgba(255,255,255,0.02)" stroke="rgba(255,255,255,0.03)"/>
              <g id="morph" transform="translate(30,40)">
                <path id="shape" d="M10 60 C 40 10, 140 10, 170 60 C 140 110, 40 110, 10 60 Z" fill="url(#g1)" opacity="0.95"></path>
              </g>
            </svg>

            <div style="margin-top:12px;color:var(--muted)">Choosing a mood updates the suggested path and the button text. That way your first step fits what you need today.</div>
          </div>
        </aside>
      </div>

      <div style="margin-top:14px;font-size:0.86rem;color:var(--muted)">
        If you are scheduling for a minor, or need documentation for an employer, please note that additional consent and administrative steps may be required. For questions, email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>.
      </div>
    </main>
  </div>

  <script>
    // Mood-to-Method for booking page
    const moodButtons = document.querySelectorAll('.moods button');
    const recHead = document.getElementById('rec-head');
    const recBody = document.getElementById('rec-body');
    const recField = document.getElementById('rec-field');
    const moodField = document.getElementById('mood-field');
    const submitBtn = document.getElementById('submit-btn');
    const shape = document.getElementById('shape');

    const map = {
